import{_ as e,a0 as i,w as o,s as p,ao as m,I as s,x as a,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"Richard Stallman 正在與癌症作戰 | LCTT x X-CMD","titleTemplate":false,"description":"Richard Stallman 正在與癌症作戰 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Richard Stallman 正在與癌症作戰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Richard Stallman 正在與癌症作戰 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230929 Richard Stallman is Battling Cancer ","title":"Richard Stallman 正在與癌症作戰","tag":"202310","desc":""},"relativePath":"202310/20230929 Richard Stallman is Battling Cancer .md","filePath":"[post].md"}'),d={name:"202310/20230929 Richard Stallman is Battling Cancer .md"};function u(h,t,g,f,S,T){const r=i("Link");return o(),p("div",null,[t[15]||(t[15]=m('<h1 id="richard-stallman-正在與癌症作戰" tabindex="-1">Richard Stallman 正在與癌症作戰 <a class="header-anchor" href="#richard-stallman-正在與癌症作戰" aria-label="Permalink to “Richard Stallman 正在與癌症作戰”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/01/163837j5enqwi9a2h6v22e.jpg" alt=""></p><blockquote><p>讓我們共同祈願他早日康復！</p></blockquote><p>為了紀念 GNU 項目成立 40 週年，自由軟件基金會（FSF）已計劃在 <strong>10 月 1 日</strong>（即GNU 40）為家庭、學生以及美國的其他人羣組織一場黑客馬拉松活動。</p><p>活動之前，GNU 項目於 9 月 27 日迎來了 40 歲生日，Richard Stallman 和一些社區成員在瑞士<ruby>比爾<rt>Biel</rt></ruby>舉行了 <ruby>GNU 黑客會議<rt>GNU Hacker&#39;s Meeting</rt></ruby>。</p><p>在會議上，他分享了自己的見解，並公開了自己正在與癌症作戰的事實。</p><p>在主題演講中，我們看到 <strong>Richard Stallman 已經沒有他標誌性的長鬍子和長髮，外貌發生了變化</strong>。他正在接受化療以對抗癌症，這就能解釋這一切。</p><p><img src="https://news.itsfoss.com/content/images/2023/09/richard-stallman-gnu-40.jpg" alt="Richard Stallman 在 GNU 黑客會議上（比爾，瑞士） | 源自：GNU.org"></p><p>他對自己的健康狀況並沒有多做説明，只是説病情是可以控制的，他仍能活很多年。</p><p>他特別強調：</p><blockquote><p>因此，這一點基本上改變了我的生活方式……我仍在為自由軟件基金會和其他的事業持續工作。</p></blockquote><h3 id="richard-matthew-stallman-rms-願你早日康復" tabindex="-1">Richard Matthew Stallman（RMS）：願你早日康復！ <a class="header-anchor" href="#richard-matthew-stallman-rms-願你早日康復" aria-label="Permalink to “Richard Matthew Stallman（RMS）：願你早日康復！”">​</a></h3><p>Richard Stallman 是一位計算機科學家，他在 <strong>1983 年 9 月 27 日</strong>公佈了名為 <strong>GNU</strong>（GNU&#39;s Not Unix）的類 Unix 操作系統。</p><p>因此，如果沒有它，Linux 就無從談起。這也是為何有些人更傾向於用 GNU/Linux 來稱呼 Linux 的原因。</p><p>值得一提的是，他還創立了 <ruby>自由軟件運動<rt>Free Software Movement</rt></ruby>，這是如今開源實踐的基石。</p><p>當然，他在許多事情上都表達了富有爭議性的觀點，但他在 Linux 和開源上的影響是巨大的！</p><p>毫無疑問，得知 Richard 患癌的消息令人難過。然而，儘管面臨這樣的困境，他以 70 歲的高齡仍然興致勃勃地出現在了主題演講中，並發表了演講。</p><p>讓我們祝願 Richard 早日恢復！💐</p><hr>',19)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),n(r,{href:"https://news.itsfoss.com/richard-stallman-battling-cancer/"},{default:l(()=>[...t[0]||(t[0]=[a("https://news.itsfoss.com/richard-stallman-battling-cancer/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),n(r,{href:"https://news.itsfoss.com/author/ankush/"},{default:l(()=>[...t[2]||(t[2]=[a("Ankush Das",-1)])]),_:1}),t[7]||(t[7]=a(" 選題：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 譯者：",-1)),n(r,{href:"https://linux.cn/lctt/ChatGPT"},{default:l(()=>[...t[4]||(t[4]=[a("ChatGPT",-1)])]),_:1}),t[9]||(t[9]=a(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[a("Linux中國",-1)])]),_:1}),t[14]||(t[14]=a(" 榮譽推出",-1))])])}const c=e(d,[["render",u]]);export{R as __pageData,c as default};
